#pragma once

// The factory preset bank. Each preset is a short text recipe, generated by
// tools/make_presets.py into FactoryPresets.cpp. The recipe is a list of
// space-separated settings:
//   paramID=value        any parameter, in its real units (Hz, seconds, index)
//   A=Table_Name         wavetable for Osc A (B= for Osc B), underscores for spaces
//   m=Source>Dest:amt    a modulation slot; add :b for bipolar
//   l1=x,y,c;x,y,c       points of LFO 1's custom shape (l2..l4 likewise)
//   fx=0,1,2,3,4,5,6     effect order
namespace cs
{
struct FactoryPreset
{
    const char* category;
    const char* name;
    const char* recipe;
};

const FactoryPreset* factoryPresets();
int numFactoryPresets();
} // namespace cs
